<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import { brewApi } from '../api';
import ProductionPlanDetail from './ProductionPlanDetail.vue';
import TankDetail from './TankDetail.vue';
const props = defineProps({ pages: { type: Array, default: () => [] } });
const emit = defineEmits(['go']);
const overview = ref(null), factory = ref(''), loading = ref(false), error = ref('');
const selectedPlan = ref(null), selectedTank = ref(null);
let timer, sequence = 0;
const number = value => Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 1 });
const time = value => value ? new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value) ? value : `${value}Z`).toLocaleTimeString('zh-CN', { hour12: false, hour: '2-digit', minute: '2-digit' }) : '—';
const canGo = page => props.pages.includes(page);
const cards = computed(() => {
  const d = overview.value;
  if (!d) return [];
  if (d.production) return [
    { label: '本月酿酒产量', value: d.production.month_volume_l, unit: 'L', note: `${d.production.month_batches} 批已完成`, page: 'production', primary: true },
    { label: '进行中的生产', value: d.production.active, unit: '批', note: '糖化、发酵与包装任务', page: 'production' },
    { label: '待出酒原液', value: d.metrics.ready_volume_l, unit: 'L', note: d.metrics.raw_location_pending ? '含罐位待核对原液' : '酿造完成，待包装或转储', page: 'factory' },
    { label: '待处理任务', value: d.metrics.open_tasks, unit: '项', note: d.overdue_tasks ? `${d.overdue_tasks} 项已超过计划时间` : '当前权限范围内待办', page: 'tasks' }
  ];
  const result = [];
  if (d.inventory) result.push({ label: '过期库存', value: d.inventory.expired, unit: '批', note: '仍有库存，需核对处理', page: 'inventory' }, { label: '待检库存', value: d.inventory.pending_quality, unit: '批', note: '质检合格后可领用', page: 'inventory' });
  if (d.purchase) result.push({ label: '待收货采购', value: d.purchase.awaiting_receipt, unit: '单', note: '已确认且尚未收齐', page: 'inventory' });
  if (d.delivery) result.push({ label: '近期交期需求', value: d.delivery.upcoming_count, unit: '单', note: '未来 7 天要求出品', page: 'production' }, { label: '待排产需求', value: d.delivery.awaiting_plan, unit: '单', note: '已确认，等待安排生产', page: 'production' });
  return result.slice(0, 3);
});
const stages = computed(() => (overview.value?.production?.stages || []).filter(stage => ['dispatch', 'mashing', 'fermentation', 'packaging', 'packing'].includes(stage.key)));
const trendTotal = computed(() => (overview.value?.production?.trend || []).reduce((sum, day) => sum + Number(day.volume_l || 0), 0));
const today = new Date().toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' });
const trendMax = computed(() => Math.max(1, ...(overview.value?.production?.trend || []).map(day => day.volume_l)));
const factorySummaries = computed(() => overview.value?.production?.factory_summaries || []);
const factoryActiveMax = computed(() => Math.max(0, ...factorySummaries.value.map(item => Number(item.active || 0))));
const factoryVolumeTotal = computed(() => factorySummaries.value.reduce((sum, item) => sum + Number(item.volume_l || 0), 0));
const factoryActiveTotal = computed(() => factorySummaries.value.reduce((sum, item) => sum + Number(item.active || 0), 0));
const factoryTrendRange = ref(30), mutedFactoryIds = ref([]);
const trendPalette = ['#ffc857', '#54e0c1', '#67b7ff', '#ff7d8b', '#bd91ff', '#ff9e57', '#70d68a', '#f17bdb'];
const factoryTrendSeries = computed(() => {
  const trends = overview.value?.production?.factory_trends || [];
  return factorySummaries.value.map((item, index) => {
    const source = trends.find(series => String(series.id) === String(item.id));
    const points = (source?.trend || []).slice(-factoryTrendRange.value);
    return { id: String(item.id), name: item.name, color: trendPalette[index % trendPalette.length], points, total: points.reduce((sum, point) => sum + Number(point.volume_l || 0), 0) };
  });
});
const factoryTrendDays = computed(() => factoryTrendSeries.value[0]?.points || []);
const factoryTrendMax = computed(() => Math.max(1, ...factoryTrendSeries.value.flatMap(series => series.points.map(point => Number(point.volume_l || 0)))));
const factoryTrendTicks = computed(() => [0, .25, .5, .75, 1].map(ratio => ({ value: factoryTrendMax.value * ratio, y: 235 - ratio * 190 })));
const factoryChartX = index => factoryTrendDays.value.length <= 1 ? 470 : 70 + index * (800 / (factoryTrendDays.value.length - 1));
const factoryChartY = value => 235 - Number(value || 0) / factoryTrendMax.value * 190;
const factoryTrendLabels = computed(() => {
  const count = factoryTrendDays.value.length;
  if (!count) return [];
  const indexes = factoryTrendRange.value === 7 ? [...Array(count).keys()] : [...new Set([0, Math.round((count - 1) / 4), Math.round((count - 1) / 2), Math.round((count - 1) * 3 / 4), count - 1])];
  return indexes.map(index => ({ index, label: factoryTrendDays.value[index].date.slice(5) }));
});
const factorySeriesPath = series => series.points.map((point, index) => `${factoryChartX(index)},${factoryChartY(point.volume_l)}`).join(' ');
const factorySeriesAreaPath = series => series.points.length ? `M ${factoryChartX(0)} 235 L ${factorySeriesPath(series).replaceAll(' ', ' L ')} L ${factoryChartX(series.points.length - 1)} 235 Z` : '';
const toggleFactorySeries = id => { mutedFactoryIds.value = mutedFactoryIds.value.includes(id) ? mutedFactoryIds.value.filter(item => item !== id) : [...mutedFactoryIds.value, id]; };
const authorizedFactories = computed(() => overview.value?.factories || []);
const isMultiFactory = computed(() => authorizedFactories.value.length > 1);
const showFactoryOverview = computed(() => isMultiFactory.value && !factory.value);
const scopedFactoryName = computed(() => authorizedFactories.value.find(item => String(item.id) === String(factory.value))?.name || authorizedFactories.value[0]?.name || '本酒厂');
const activeTanks = computed(() => (overview.value?.tanks || []).filter(tank => tank.volume_l > 0 || ['mashing', 'fermentation', 'finish'].includes(tank.stage)).slice(0, 4));
const emptyTanks = computed(() => (overview.value?.tanks || []).filter(tank => tank.status === 'empty').length);
const tankState = tank => tank.stage_label || ({ empty: '空罐', ready: '待包装', fermenting: '发酵中', cold_crash: '冷贮', conditioning: '后发酵', cleaning: '清洗中', maintenance: '维护中', abnormal: '异常' })[tank.status] || '未知状态';
async function load() {
  const request = ++sequence; loading.value = true; error.value = '';
  try { const data = await brewApi.getDashboard(factory.value ? { factory_id: factory.value } : {}); if (request === sequence) overview.value = data; }
  catch (cause) { if (request === sequence) error.value = cause.message || '看板加载失败，请重试。'; }
  finally { if (request === sequence) loading.value = false; }
}
onMounted(() => { load(); timer = window.setInterval(() => { if (!loading.value && !selectedPlan.value && !selectedTank.value) load(); }, 60000); });
onUnmounted(() => { sequence++; window.clearInterval(timer); });
</script>
<template>
<div class="overview-dashboard">
  <header class="dashboard-heading"><div><span class="dashboard-eyebrow">{{ isMultiFactory ? '总部 · 多厂区生产总览' : '酒厂 · 本厂生产总览' }}</span><h2>{{ isMultiFactory ? (factory ? scopedFactoryName + ' · 生产情况' : '各厂区生产情况，一屏掌握') : scopedFactoryName + ' · 生产运营看板' }}</h2><p>{{ today }}<span v-if="overview"> · 数据更新于 {{ time(overview.as_of) }}</span><span v-if="!isMultiFactory"> · 仅显示当前账号授权酒厂的数据</span></p></div><div class="dashboard-controls"><select v-if="isMultiFactory" v-model="factory" aria-label="筛选厂区" :disabled="loading" @change="load"><option value="">全部授权厂区</option><option v-for="item in overview?.factories || []" :key="item.id" :value="item.id">{{ item.name }}</option></select><span v-else-if="authorizedFactories.length === 1" class="factory-scope-badge">{{ scopedFactoryName }}</span><button class="btn btn-sm btn-outline" :disabled="loading" @click="load">{{ loading ? '刷新中…' : '刷新数据' }}</button></div></header>
  <div v-if="error" class="master-error" role="alert">{{ error }}<span v-if="overview"> · 当前显示上次成功加载的数据</span></div>
  <div v-if="!overview" class="empty">{{ loading ? '正在加载业务数据…' : '点击刷新重试' }}</div>
  <template v-else>
    <div class="overview-kpis"><article v-for="(card,index) in cards" :key="card.label" :class="{ primary: card.primary }"><header><span>{{ card.label }}</span><span class="kpi-symbol" aria-hidden="true">{{ ['◷','↗','◈','≡'][index] }}</span></header><div><strong>{{ number(card.value) }}</strong><b>{{ card.unit }}</b></div><footer><small>{{ card.note }}</small><button v-if="canGo(card.page)" :aria-label="'查看' + card.label" @click="emit('go', card.page)">↗</button></footer></article></div>
    <section v-if="showFactoryOverview" class="factory-overview"><header><div><strong>厂区生产对比</strong><span>本月完工产量与当前进行中的生产计划 · 点击厂区查看生产明细</span></div><b>{{ factorySummaries.length }} 个授权厂区</b></header><div class="factory-overview-summary"><div><span>本月总产量</span><strong>{{ number(factoryVolumeTotal) }}<small>L</small></strong></div><div><span>进行中生产</span><strong>{{ factoryActiveTotal }}<small>批</small></strong></div><div><span>本月完工批次</span><strong>{{ factorySummaries.reduce((sum, item) => sum + Number(item.batches || 0), 0) }}<small>批</small></strong></div></div><div class="factory-charts"><article class="factory-chart-card history-chart-card"><header class="history-chart-heading"><div class="history-chart-title"><span class="history-chart-icon">↗</span><div><strong>厂区产量走势</strong><span>完工实录 · 升（L）</span></div></div><div class="factory-range-toggle" role="group" aria-label="选择历史产量范围"><button v-for="range in [7, 30]" :key="range" :class="{ active: factoryTrendRange === range }" @click="factoryTrendRange = range">近 {{ range }} 天</button></div></header><div class="factory-trend-legend" aria-label="显示或隐藏厂区曲线"><button v-for="series in factoryTrendSeries" :key="series.id" :class="{ muted: mutedFactoryIds.includes(series.id) }" @click="toggleFactorySeries(series.id)"><i :style="{ '--series-color': series.color }"></i><span>{{ series.name }}</span><b>{{ number(series.total) }}<small>L</small></b></button></div><div v-if="factoryTrendDays.length" class="factory-line-chart-wrap"><svg class="factory-line-chart" viewBox="0 0 900 310" role="img" :aria-label="'近' + factoryTrendRange + '天各厂区历史产量曲线'"><defs><linearGradient v-for="series in factoryTrendSeries" :key="'fill-' + series.id" :id="'factory-fill-' + series.id" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" :stop-color="series.color" stop-opacity=".3"/><stop offset="100%" :stop-color="series.color" stop-opacity=".015"/></linearGradient><filter id="factory-curve-glow" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="3" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><g v-for="tick in factoryTrendTicks" :key="tick.value"><line x1="70" x2="870" :y1="tick.y" :y2="tick.y" class="factory-chart-gridline"/><text x="58" :y="tick.y + 4" text-anchor="end" class="factory-chart-axis-label">{{ number(tick.value) }}</text></g><line x1="70" y1="45" x2="70" y2="235" class="factory-chart-axis"/><line x1="70" y1="235" x2="870" y2="235" class="factory-chart-axis"/><g v-for="label in factoryTrendLabels" :key="label.index"><line :x1="factoryChartX(label.index)" y1="235" :x2="factoryChartX(label.index)" y2="241" class="factory-chart-axis"/><text :x="factoryChartX(label.index)" y="264" text-anchor="middle" class="factory-chart-axis-label">{{ label.label }}</text></g><g v-for="series in factoryTrendSeries" :key="series.id" v-show="!mutedFactoryIds.includes(series.id)"><path :d="factorySeriesAreaPath(series)" :fill="'url(#factory-fill-' + series.id + ')'"/><polyline :points="factorySeriesPath(series)" fill="none" :stroke="series.color" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" filter="url(#factory-curve-glow)"/></g></svg></div><p v-else class="overview-empty">暂无历史产量数据</p><footer class="factory-chart-footnote"><span><i></i>按批次完工日期统计</span><span>点击图例可单独查看厂区</span></footer></article><article class="factory-chart-card active-chart"><header><div><strong>进行中的生产</strong><span>糖化、发酵、待包装及包装执行</span></div><b>当前任务</b></header><div class="factory-chart-list"><button v-for="item in [...factorySummaries].sort((a,b) => Number(b.active || 0) - Number(a.active || 0))" :key="item.id" class="factory-chart-row" @click="factory = item.id; load()"><span class="factory-chart-label"><strong>{{ item.name }}</strong><small>生产计划</small></span><span class="factory-chart-track"><i :style="{ width: factoryActiveMax > 0 && item.active > 0 ? Math.max(3, item.active / factoryActiveMax * 100) + '%' : '0%' }"></i></span><b class="factory-chart-value">{{ item.active }}<small>批</small></b></button><p v-if="!factorySummaries.length" class="overview-empty">暂无授权酒厂数据</p></div></article></div></section>
    <div class="dashboard-columns">
      <div class="dashboard-primary">
        <section v-if="overview.production" class="panel production-panel"><header class="panel-header"><div><div class="panel-title">生产与包装进度</div><div class="panel-subtitle">从下发到包装，跟进当前批次</div></div><button v-if="canGo('production')" class="overview-link" @click="emit('go', 'production')">全部生产 →</button></header><div class="overview-stages"><div v-for="(stage,index) in stages" :key="stage.key"><span class="stage-caption"><i></i>{{ stage.label }}</span><strong :class="{ highlighted: stage.count > 0 }">{{ stage.count }}<small>批</small></strong></div></div><div class="overview-batches"><div class="list-caption"><span>最近生产批次</span><span>当前阶段</span></div><button v-for="plan in overview.production.recent.slice(0,4)" :key="plan.id" class="overview-batch" @click="selectedPlan = plan.id"><div class="batch-monogram" aria-hidden="true">酿</div><div class="batch-description"><strong>{{ plan.product }}</strong><small>{{ plan.name }} · {{ number(plan.volume_l) }} L · {{ plan.owner }}</small></div><span class="batch-status" :class="{ done: plan.stage === 'done' }">{{ plan.stage_label }}</span><b class="batch-arrow">›</b></button><p v-if="!overview.production.recent.length" class="overview-empty">暂无生产计划，下发后可在这里跟进进度</p></div></section>
        <section v-if="overview.production" class="panel trend-panel"><header class="panel-header"><div><div class="panel-title">近 7 天酿酒产量</div><div class="panel-subtitle">按完成日期与实录体积统计（无产出记录时采用进罐体积）</div></div><div class="trend-total"><strong>{{ number(trendTotal) }}</strong><span>L / 7 天</span></div></header><div class="overview-chart" role="img" :aria-label="'近七天产量合计' + number(trendTotal) + '升'"><div v-for="day in overview.production.trend" :key="day.date" class="overview-chart-day"><strong>{{ number(day.volume_l) }}</strong><div class="overview-chart-track"><div :style="{ height: (day.volume_l / trendMax * 100) + '%' }"></div></div><span>{{ day.date.slice(5) }}</span></div></div></section>
        <section v-if="overview.delivery" class="panel"><header class="panel-header"><div><div class="panel-title">近期交付安排</div><div class="panel-subtitle">未来 7 天要求出品的产品需求</div></div><button v-if="canGo('production')" class="overview-link" @click="emit('go','production')">查看需求 →</button></header><div class="overview-batches"><div v-for="item in overview.delivery.upcoming.slice(0,3)" :key="item.id" class="overview-batch"><div class="batch-description"><strong>{{ item.product }}</strong><small>{{ number(item.volume_l) }} L</small></div><span class="delivery-date">{{ item.date }}</span></div><p v-if="!overview.delivery.upcoming.length" class="overview-empty">未来 7 天暂无交期需求</p></div></section>
      </div>

    </div>
    <section v-if="overview.sections.production" class="panel tanks-panel"><header class="panel-header"><div><div class="panel-title">罐体运行概况</div><div class="panel-subtitle">{{ overview.tanks?.length || 0 }} 个罐体 · {{ emptyTanks }} 个空罐</div></div><button v-if="canGo('factory')" class="overview-link" @click="emit('go','factory')">全部罐体 →</button></header><div class="overview-tanks"><button v-for="tank in activeTanks" :key="tank.id" @click="selectedTank = tank.id"><div class="tank-illustration" aria-hidden="true"><div :style="{ height: Math.min(100,Math.max(0,tank.capacity_l ? tank.volume_l / tank.capacity_l * 100 : 0)) + '%' }"></div><i></i></div><div class="tank-facts"><header><strong>{{ tank.name }}</strong><span>{{ tankState(tank) }}</span></header><p>{{ tank.product || tank.factory }}</p><div><b>{{ number(tank.volume_l) }}</b><small> / {{ number(tank.capacity_l) }} L</small></div></div><span class="tank-arrow">›</span></button><p v-if="!activeTanks.length" class="overview-empty">暂无在用罐体</p></div></section>
  </template>
  <ProductionPlanDetail :plan-id="selectedPlan" @close="selectedPlan = null" @changed="load" />
  <TankDetail :tank-id="selectedTank" @close="selectedTank = null" />
</div>
</template>
<style scoped>
